    "diseaseOutcome": "Cerebral Vascular Accident",
    "ruleSummary": "CEREBRAL VASCULAR ACCIDENT {C.V.A.) Cerebral Vascular Accident (CV.A.), or sudden bleeding in the brain, has some identifiable astrological patterns based on current observa tions. If the Sun is positioned in the 10th house and influences the 1 st, 4th, 6th, or 9th houses through Rahu or Mars, internal mental restlessness can disrupt blood flow in the brain (9th house). This dis ruption may cause bleeding through the nose or mouth. If the bleed ing cannot escape, it clots, leading to severe complications. Additionally, when Mars and Ketu conjunct in the 10th house and in fluence the 1 st and 8th houses, they can block blood flow in the brain, causing the veins to rupture and resulting in bleeding. Ketu's influ ence can also cause clotting, further worsening the condition. From the birth charts I have analyzed, one significant observation stands out. If Venus and Mars are positioned in Aries in the 3rd house, and Aries rules the 4th house, Mars in the 8th house in Venus's nakshatra (constellation) sits in the Sun's sign, and the Moon acts as the 8th lord. During the Moon's main dasha (period) and the Sun's sub-dasha, the native experiences a cerebral attack, leading to death.",
