    "ruleSummary": "SPINE PROBLEMS: SPONDYLITIS AND ARTHRITIS In Indian astrology, the ninth house (bhava) is considered the waist. The tenth house governs the area from the thigh to the knees. From the knees to the ankles is also covered by the tenth house, while the twelfth house rules from the ankles to the feet. However, in Assyrian astrology, the ninth house has two branches: one extends downward to the lower body, while the other moves upward. The exact center of the back corresponds to the tenth house, the neck to the eleventh house, and the back of the head to the twelfth house. Role of Planets in Spondylitis - While Saturn (Shani) is the primary planet responsible for spondylitis, Mercury (Budh) and Ketu also play significant roles in this condition. - If Saturn influences the 3rd, 8th, or 12th houses, spondylitis is likely to occur. - If Saturn aspects Mercury's house, is in Mercury's house, or has any direct relationship with Mercury, the condition becomes more pro nounced. - For instance, if Saturn, as the ruler of the 8th house, sits in the 12th house and aspects the 2nd house, it can cause not just dental prob lems but also jaw issues, potentially leading to \"lockjaw\" (Lock 5). Role of Ketu in Arthritis - When Ketu is in a water sign and any nakshatra (constellation), it indicates arthritis. The effect is stronger in Jupiter's nakshatra but even more pronounced in Saturn or Mer cury's nakshatra. - Ketu consumes the characteristics of the sign it occupies. - If Ketu resides in a water sign, it dries up the fluid present in the joints, leading to arthritis. Cancer (Karka) is Known as the fourth house of Kalpurusha or the bedroom, if Ketu is in Cancer, pain in the waist or legs begins dur ing sleep. If Ketu is in Scorpio, the pain manifests in the bathroom or shower. If Ketu...",
